"""The artifacts of the openbao example, generated by the Python SDK, are the ones the Go example generates
(examples/openbao/golden, written by `go test ./examples/openbao/go`)."""

import json
import tempfile
import unittest
from pathlib import Path

import openbao
from packsdk import generate

GOLDEN = Path(__file__).resolve().parent.parent / "golden"


def tree(d: Path) -> list[str]:
    return sorted(p.relative_to(d).as_posix() for p in d.rglob("*") if p.is_file())


class Golden(unittest.TestCase):
    def test_equals_the_go_example(self):
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp)
            generate(out, openbao.OpenBao())
            self.assertEqual(tree(GOLDEN), tree(out))
            for rel in tree(GOLDEN):
                want, got = (GOLDEN / rel).read_bytes(), (out / rel).read_bytes()
                if rel.endswith(".json"):
                    self.assertEqual(json.loads(want), json.loads(got), rel)
                else:
                    self.assertEqual(want.decode(), got.decode(), rel)


class Cel(unittest.TestCase):
    """The CEL the pack speaks: the declaration in Python is the one the Go render evaluates."""

    def test_formula(self):
        formulas = openbao.OpenBao().pack_compute()
        self.assertEqual(["/openbao/storage"], list(formulas))
        expr = formulas["/openbao/storage"]
        for want in ("has(pack.values.postgres)", "'postgresql'", "connection_url", "${secret:",
                     "pack.keys.postgres.instances[0]", "ports.pg", "pack.values.postgres.database"):
            self.assertIn(want, expr)

    def test_rule(self):
        rules = openbao.OpenBao().pack_rules()
        self.assertEqual(["/openbao/storage"], list(rules))
        (rule,) = rules["/openbao/storage"]
        self.assertEqual("!has(pack.values.postgres) || !has(values.openbao.storage)"
                         " || size(values.openbao.storage) == 0", rule.rule)
        self.assertTrue(rule.message)
        self.assertEqual([], rule.phases)  # an unphased rule is the operator's document's (preMutate)

    def test_schema_carries_them(self):
        pack = openbao.OpenBao()
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp)
            generate(out, pack)
            s = json.loads((out / "openbao" / "schema.json").read_text())
        storage = s["properties"]["openbao"]["properties"]["storage"]
        self.assertEqual(pack.pack_compute()["/openbao/storage"], storage["x-pack-compute"])
        # the rule as written, and its message in the other languages of docs/
        written = [{k: v for k, v in r.items() if k != "x-pack-i18n"} for r in storage["x-pack-rules"]]
        self.assertEqual([r.to_json() for r in pack.pack_rules()["/openbao/storage"]], written)
        (rule,) = storage["x-pack-rules"]
        self.assertNotIn("phases", rule)
        self.assertIn("ru", rule["x-pack-i18n"])


if __name__ == "__main__":
    unittest.main()
